sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

	var swiftSource = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_swift_populate_swift_exception');

    //MSSCUSTODY-4197: Once the swift message with "Rejected"/ "completed" status created, the "exception" text should be populated to the corresponding shell trade and PAPP & PRPR trade
	if (current.trade_id && current.trade_id.trim() != '') {
        var grTrade = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
        if (grTrade.get(current.trade_id)) {
			// MSSCUSTODY-3591
			grTrade.sender_id = current.sender_id;
			grTrade.swift_exception_message = current.exception_message_text;
			grTrade.update();
			//========Hiding for MSSCUSTODY-7195
            // if (current.message_status == 'rejected' && (swiftSource.indexOf(grTrade.source_system) > -1)) { //Shell Trades (source system is CFS, HUB-MAS) // MSSCUSTODY-4764 - Added a source system check for SWIFT from system property as new swift sources are introduced for GCS 
            //     grTrade.swift_exception_message = current.exception_message_text;				
            //     grTrade.update();
            // } else if (current.message_status == 'completed' && (grTrade.source_system == 'GHSS' || grTrade.source_system == 'GCS') && (grTrade.trade_lifecycle_status == 'TradCaptrdPdgApprvl' || grTrade.trade_lifecycle_status == 'TradCaptrdInErr')) { //Actual Trades (source system is GHSS) with trade lifecycle status is "Trade Captured - Pending Approval" (PAPP) or "Trade Captured In Error" (PRPR) // MSSCUSTODY-4764
            //     grTrade.swift_exception_message = current.exception_message_text;
            //     grTrade.update();
            // }
			//========
        }
    }
    //gs.info('MSSCUSTODY-4197 - Business Rule PopulateExceptionMessageToInscopeTrades Execution Completed');

})(current, previous);
